<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/ShopAccessFixture.php';
require_once __DIR__.'/Support/ReviewedListingFixture.php';
use DigiForge\Database\Tables;
final class ListingEvidenceAcceptanceTest extends WP_UnitTestCase {
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();ShopAccessFixture::reset();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['digital','personalized_pod','standard_pod','jewelry'],DigiForge\Core\Capabilities::ALL);global $wpdb;$wpdb->query('START TRANSACTION');}
 private function render():string {$get=$_GET;try{$_GET=['df_view'=>'listings','df_shop'=>'digital'];return (new DigiForge\Portal\Portal())->render();}finally{$_GET=$get;}}
 public function testConfirmedDigitalUploadIsVisibleOnlyInItsStoredShopAndNeverGrantsPublish():void {
  $f=ReviewedListingFixture::create($this);global $wpdb;$table=$wpdb->prefix.'digiforge_etsy_operations';$upload=$wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE intent_id=%d AND operation_type='UPLOAD_FILE' AND state='CONFIRMED_SUCCESS'",$f['intent']),ARRAY_A);self::assertIsArray($upload);$id=(int)$upload['id'];self::assertSame(1,$wpdb->update($table,['shop_reference'=>'digital'],['id'=>$id]));$foreign=$upload;unset($foreign['id']);$foreign['shop_reference']='jewelry';$foreign['idempotency_key']=wp_generate_uuid4();$foreign['external_asset_reference']='989898';self::assertSame(1,$wpdb->insert($table,$foreign));$html=$this->render();self::assertStringContainsString('#'.$id.'</td><td>digital</td><td>5678</td><td>9012',$html);self::assertStringNotContainsString('989898',$html);self::assertStringContainsString('CONFIRMED_IDENTITY_RECORDED',$html);self::assertStringContainsString('NO UPLOAD / NO PUBLISH',$html);self::assertTrue(DigiForge\Core\Settings::safety_locked());
 }
 public function testSelectedWebhookScopePrecedesWindowAndCannotCountForeignReceipts():void {
  global $wpdb;$table=Tables::webhook_evidence();$now=current_time('mysql',true);$ids=[];foreach(['digital','jewelry']as $shop){self::assertSame(1,$wpdb->insert($table,['provider'=>'etsy','event_id'=>'scope-'.wp_generate_uuid4(),'event_type'=>'ORDER.PAID','shop_reference'=>$shop,'verification_status'=>'VERIFIED','processing_status'=>'PROCESSED','body_sha256'=>hash('sha256','synthetic offline receipt'),'result_hash'=>hash('sha256',$shop),'received_at'=>$now,'processed_at'=>$now]));$ids[$shop]=(int)$wpdb->insert_id;}
  $model=new DigiForge\Listings\WebhookReconciliationReadModel();$result=$model->snapshot('etsy',1,'digital');self::assertSame('AVAILABLE',$result['evidence_state']);self::assertSame([$ids['digital']],array_map('intval',array_column($result['events'],'id')));self::assertSame(1,$result['counts']['processed']);self::assertFalse($result['retry_performed']);$full=$model->snapshot('etsy',50,'digital');$html=$this->render();self::assertStringContainsString('<span>Processed</span><b>'.$full['counts']['processed'].'</b>',$html);self::assertStringContainsString('Selected-shop verified inbound evidence',$html);self::assertNotContains($ids['jewelry'],array_map('intval',array_column($full['events'],'id')));
  $filter=static fn(string $sql):string=>str_contains($sql,'FROM '.$table)?'SELECT * FROM missing_scoped_webhook_evidence':$sql;$prior=$wpdb->suppress_errors(true);add_filter('query',$filter);try{self::assertSame('UNAVAILABLE',$model->snapshot('etsy',1,'digital')['evidence_state']);self::assertStringContainsString('Zero counts are not asserted',$this->render());}finally{remove_filter('query',$filter);$wpdb->suppress_errors($prior);}self::assertSame('UNAVAILABLE',$model->snapshot('etsy',1,'unknown')['evidence_state']);
 }
 public function testNumericWebhookShopRequiresMatchingEventOrderAndEnvironmentBoundIdentity():void {
  global $wpdb;$now=current_time('mysql',true);$event='numeric-scope-'.wp_generate_uuid4();self::assertSame(1,$wpdb->insert(Tables::webhook_evidence(),['provider'=>'etsy','event_id'=>$event,'event_type'=>'ORDER.PAID','shop_reference'=>'68031896','verification_status'=>'VERIFIED','processing_status'=>'PROCESSED','body_sha256'=>hash('sha256','offline numeric receipt'),'result_hash'=>hash('sha256',$event),'received_at'=>$now,'processed_at'=>$now]));$receipt=(int)$wpdb->insert_id;
  $order=(new DigiForge\Orders\Repository())->createOrder(['channel'=>'etsy','environment'=>'production','external_order_reference'=>'scope-order-'.wp_generate_uuid4(),'shop_reference'=>'68031896'],'etsy_webhook:'.$event);self::assertNotWPError($order);self::assertSame(1,$wpdb->insert(Tables::integrations(),['provider'=>'etsy','environment'=>'sandbox','connection_key'=>wp_generate_uuid4(),'display_name'=>'Synthetic identity only','status'=>'CONFIGURED','enabled'=>0,'config'=>wp_json_encode(['_connection_test'=>['ok'=>true,'details'=>['shop_id'=>68031896,'shop_name'=>'DigicraftifyShop']]]),'created_at'=>$now,'updated_at'=>$now]));$model=new DigiForge\Listings\WebhookReconciliationReadModel();self::assertNotContains($receipt,array_map('intval',array_column($model->snapshot('etsy',1,'personalized_pod')['events'],'id')));
  self::assertSame(1,$wpdb->update(Tables::orders(),['environment'=>'sandbox'],['id'=>$order['id']]));self::assertSame([$receipt],array_map('intval',array_column($model->snapshot('etsy',1,'personalized_pod')['events'],'id')));self::assertSame(1,$wpdb->update(Tables::orders(),['idempotency_key'=>'unrelated-event'],['id'=>$order['id']]));self::assertNotContains($receipt,array_map('intval',array_column($model->snapshot('etsy',1,'personalized_pod')['events'],'id')));
 }

}
